import { cva, type VariantProps } from "class-variance-authority";
import { InfoIcon } from "lucide-react";
import React from "react";

import { cn, type SharedProps } from "@/registry/base-nova/protoform/lib/utils";

const alertVariants = cva(
  "relative grid w-full grid-cols-[0_1fr] items-start gap-y-0.5 rounded-lg border px-4 py-3 text-sm has-[>svg]:grid-cols-[calc(var(--spacing)*4)_1fr] has-[>svg]:gap-x-3 [&>svg]:size-4 [&>svg]:translate-y-0.5 [&>svg]:text-current",
  {
    defaultVariants: {
      variant: "info",
    },
    variants: {
      variant: {
        destructive:
          "!border-destructive/20 bg-destructive/10 text-destructive *:data-[slot=alert-description]:text-destructive/90 [&>href]:text-current [&>svg]:text-current",
        info: "bg-card text-card-foreground",
        success:
          "!border-green-200 dark:!border-green-800/40 bg-green-50 text-green-800 *:data-[slot=alert-description]:text-green-800 dark:bg-green-950/30 dark:text-green-300 dark:*:data-[slot=alert-description]:text-green-300 [&>href]:text-current [&>svg]:text-current",
        warning:
          "!border-blue-200 bg-blue-50 text-blue-800 *:data-[slot=alert-description]:text-blue-800 [&>href]:text-current [&>svg]:text-current",
      },
    },
  }
);

const Alert = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> & VariantProps<typeof alertVariants> & SharedProps & { icon?: React.ReactNode }
>(({ className, variant, testId, icon = <InfoIcon />, children, ...props }, ref) => (
  <div
    className={cn(alertVariants({ variant }), className)}
    data-slot="alert"
    data-testid={testId}
    ref={ref}
    role="alert"
    {...props}
  >
    {icon}
    {children}
  </div>
));

Alert.displayName = "Alert";

const AlertTitle = React.forwardRef<HTMLDivElement, React.ComponentProps<"div"> & SharedProps>(
  ({ className, testId, ...props }, ref) => (
    <div
      className={cn("col-start-2 line-clamp-1 min-h-4 font-medium tracking-tight", className)}
      data-slot="alert-title"
      data-testid={testId}
      ref={ref}
      {...props}
    />
  )
);

AlertTitle.displayName = "AlertTitle";

const AlertDescription = React.forwardRef<HTMLDivElement, React.ComponentProps<"div"> & SharedProps>(
  ({ className, testId, ...props }, ref) => (
    <div
      className={cn(
        "col-start-2 grid w-full min-w-0 justify-items-start gap-1 text-muted-foreground text-sm [&_p]:leading-relaxed [&_pre]:w-full",
        className
      )}
      data-slot="alert-description"
      data-testid={testId}
      ref={ref}
      {...props}
    />
  )
);

AlertDescription.displayName = "AlertDescription";

export { Alert, AlertDescription, AlertTitle };

import type { ParsedField } from "./core-types";
import type { DataProviderRegistry } from "./data-providers";
import { AutoFormFieldComponentRegistry, defaultRegistry } from "./fields";
import { readDataProviderId } from "./fields/shared";
import { getFieldUiConfig, resolveRenderFieldType } from "./helpers";
import { buildFieldMatchContext, type FieldTypeRegistry } from "./registry";
import { mergeFieldOverrides, protoConversionOptionsFromFieldConfig, resolveSchema } from "./schema";
import type { AutoFormSchemaInput, FieldConfigMap } from "./types";

export type AutoFormConfigurationDiagnosticCode =
  | "invalid-configuration-path"
  | "missing-data-provider"
  | "missing-renderer"
  | "unsupported-configuration";

export interface AutoFormConfigurationDiagnostic {
  code: AutoFormConfigurationDiagnosticCode;
  message: string;
  path: string;
  severity: "error";
}

export interface InspectAutoFormConfigurationInput<
  T extends Record<string, unknown> = Record<string, unknown>,
  TCustomFieldType extends string = never,
> {
  dataProviders?: DataProviderRegistry;
  fieldConfig?: FieldConfigMap<TCustomFieldType>;
  fieldRegistry?: FieldTypeRegistry<string>;
  schema: AutoFormSchemaInput<T>;
}

const STRUCTURAL_FIELD_TYPES = new Set(["array", "map", "object", "oneof"]);

function collectFields(
  fields: ParsedField[],
  path: readonly string[] = []
): Array<{ field: ParsedField; path: string }> {
  return fields.flatMap((field) => {
    const fieldPath = [...path, field.key];
    return [{ field, path: fieldPath.join(".") }, ...collectFields(field.schema ?? [], fieldPath)];
  });
}

function resolvedRenderer(field: ParsedField, registry: FieldTypeRegistry<string>): string {
  const configured = getFieldUiConfig(field).control;
  if (configured) {
    return configured;
  }
  return registry.resolve(field, buildFieldMatchContext(field))?.name ?? resolveRenderFieldType(field);
}

function hasRenderer(field: ParsedField, renderer: string, registry: FieldTypeRegistry<string>): boolean {
  if (STRUCTURAL_FIELD_TYPES.has(field.type) && renderer === field.type) {
    return true;
  }
  if (renderer !== "fallback" && Object.hasOwn(AutoFormFieldComponentRegistry, renderer)) {
    return true;
  }
  return registry.list().some((definition) => definition.name === renderer);
}

function fieldDiagnostics(
  field: ParsedField,
  path: string,
  registry: FieldTypeRegistry<string>,
  dataProviders: DataProviderRegistry | undefined
): AutoFormConfigurationDiagnostic[] {
  const diagnostics: AutoFormConfigurationDiagnostic[] = [];
  const renderer = resolvedRenderer(field, registry);
  if (!hasRenderer(field, renderer, registry)) {
    diagnostics.push({
      code: "missing-renderer",
      message: `Renderer "${renderer}" is not registered.`,
      path,
      severity: "error",
    });
  }

  const dataProviderId = readDataProviderId(field);
  if (dataProviderId !== undefined) {
    if (!dataProviders?.[dataProviderId]) {
      diagnostics.push({
        code: "missing-data-provider",
        message: `Data provider "${dataProviderId}" is not registered.`,
        path,
        severity: "error",
      });
    }
    if (field.type !== "string" && field.type !== "number") {
      diagnostics.push({
        code: "unsupported-configuration",
        message: "Data providers are supported only on scalar string or number fields.",
        path,
        severity: "error",
      });
    }
  }

  if (
    field.fieldConfig?.emptyRepeatedStringPolicy &&
    !(field.type === "array" && field.schema?.[0]?.type === "string")
  ) {
    diagnostics.push({
      code: "unsupported-configuration",
      message: "emptyRepeatedStringPolicy is supported only on repeated string fields.",
      path,
      severity: "error",
    });
  }

  return diagnostics;
}

export function inspectAutoFormConfiguration<
  T extends Record<string, unknown> = Record<string, unknown>,
  TCustomFieldType extends string = never,
>({
  schema,
  fieldConfig,
  fieldRegistry,
  dataProviders,
}: InspectAutoFormConfigurationInput<T, TCustomFieldType>): AutoFormConfigurationDiagnostic[] {
  const resolvedSchema = resolveSchema(schema, protoConversionOptionsFromFieldConfig(fieldConfig));
  const fields = mergeFieldOverrides(resolvedSchema.parsedSchema.fields, fieldConfig);
  const flattenedFields = collectFields(fields);
  const validPaths = new Set(flattenedFields.map((entry) => entry.path));
  const activeRegistry = fieldRegistry ?? defaultRegistry;
  const diagnostics: AutoFormConfigurationDiagnostic[] = [];

  for (const path of Object.keys(fieldConfig ?? {})) {
    if (!validPaths.has(path)) {
      diagnostics.push({
        code: "invalid-configuration-path",
        message: `Field configuration path "${path}" does not exist in the schema.`,
        path,
        severity: "error",
      });
    }
  }

  for (const { field, path } of flattenedFields) {
    diagnostics.push(...fieldDiagnostics(field, path, activeRegistry, dataProviders));
  }

  return diagnostics.sort((left, right) => left.path.localeCompare(right.path) || left.code.localeCompare(right.code));
}

import React from "react";

import type { AutoFormFieldComponents, AutoFormUIComponents, ParsedField } from "./core-types";
import type { DataProviderRegistry } from "./data-providers";
import { getPathInObject } from "./field-utils";
import type { FieldTypeRegistry } from "./registry";
import type { AutoFormUiRule, DeprecatedFieldPolicy } from "./types";

export interface AutoFormContextValue {
  dataProviders?: DataProviderRegistry | undefined;
  deprecatedFields: DeprecatedFieldPolicy;
  evaluateRules: (rules: AutoFormUiRule[] | undefined, fieldValue?: unknown) => boolean;
  fieldRegistry?: FieldTypeRegistry<string> | undefined;
  formComponents: AutoFormFieldComponents;
  formValues: Record<string, unknown>;
  getFieldUiConfig: (field: ParsedField) => Record<string, unknown>;
  testIdPrefix: string;
  uiComponents: AutoFormUIComponents;
}

export const AutoFormContext = React.createContext<AutoFormContextValue | null>(null);

export function useAutoForm(): AutoFormContextValue {
  const context = React.useContext(AutoFormContext);
  if (!context) {
    throw new Error("useAutoForm must be used inside an AutoForm component.");
  }
  return context;
}

export function useAutoFormField(path: string[]) {
  const { formValues, evaluateRules, getFieldUiConfig: getUiConfig, testIdPrefix } = useAutoForm();
  const fieldValue = getPathInObject(formValues, path);

  return {
    evaluateRules,
    fieldValue,
    getFieldUiConfig: getUiConfig,
    testIdPrefix,
  };
}

// ---------------------------------------------------------------------------
// Legacy aliases – kept during migration, will be removed once all consumers
// switch to useAutoForm().
// ---------------------------------------------------------------------------

export type InternalAutoFormRenderContextValue = Pick<AutoFormContextValue, "uiComponents" | "formComponents">;
export type InternalAutoFormRuntimeContextValue = Pick<
  AutoFormContextValue,
  "deprecatedFields" | "formValues" | "evaluateRules" | "fieldRegistry" | "getFieldUiConfig" | "testIdPrefix"
>;

export const AutoFormRenderContext = AutoFormContext;
export const AutoFormRuntimeContext = AutoFormContext;

export function useAutoFormRenderContext(): InternalAutoFormRenderContextValue {
  return useAutoForm();
}

export function useAutoFormRuntimeContext(): InternalAutoFormRuntimeContextValue {
  return useAutoForm();
}

import type React from "react";
import type { ReactNode } from "react";

// Re-export schema contract types from shared lib so existing consumers
// can continue importing from './core-types' without changes.
export type {
  FieldConfig,
  FieldWrapperProps,
  ParsedField,
  ParsedSchema,
  Renderable,
  SchemaProvider,
  SchemaValidation,
  SchemaValidationContext,
  SchemaValidationError,
  UiRenderable,
} from "../../lib/form-types";

import type { FieldWrapperProps, ParsedField, UiRenderable } from "../../lib/form-types";

export { getFieldHints } from "../../lib/form-types";

// ---------------------------------------------------------------------------
// UI component contracts — AutoForm-specific wrapper and field props.
// ---------------------------------------------------------------------------

export interface ObjectWrapperProps {
  children: ReactNode;
  field: ParsedField;
  hasError?: boolean | undefined;
  label: UiRenderable;
}

export interface ArrayWrapperProps {
  children: ReactNode;
  field: ParsedField;
  label: UiRenderable;
  onAddItem: () => void;
}

export interface ArrayElementWrapperProps {
  children: ReactNode;
  index: number;
  onRemove: () => void;
}

export interface AutoFormUIComponents {
  ArrayElementWrapper: React.ComponentType<ArrayElementWrapperProps>;
  ArrayWrapper: React.ComponentType<ArrayWrapperProps>;
  ErrorMessage: React.ComponentType<{ error: string }>;
  FieldWrapper: React.ComponentType<FieldWrapperProps>;
  Form: React.ComponentType<React.ComponentProps<"form">>;
  ObjectWrapper: React.ComponentType<ObjectWrapperProps>;
  SubmitButton: React.ComponentType<{
    children: ReactNode;
    disabled?: boolean | undefined;
    testId?: string | undefined;
  }>;
}

export interface AutoFormInputProps {
  checked?: boolean;
  disabled?: boolean;
  indeterminate?: boolean;
  max?: number | string;
  min?: number | string;
  name?: string;
  onBlur: () => void;
  onChange: AutoFormValueHandler;
  onCheckedChange: AutoFormCheckedHandler;
  onValueChange: AutoFormValueHandler;
  placeholder?: string;
  ref?: React.Ref<HTMLInputElement>;
  required?: boolean;
  step?: number | string;
  testId?: string;
  value?: unknown;
  [name: string]: unknown;
}

interface AutoFormSetValueOptions {
  shouldDirty?: boolean;
  shouldTouch?: boolean;
  shouldValidate?: boolean;
}

type AutoFormValueHandler = {
  bivarianceHack(value: unknown, options?: AutoFormSetValueOptions): void;
}["bivarianceHack"];

type AutoFormCheckedHandler = {
  bivarianceHack(value: boolean): void;
}["bivarianceHack"];

export interface AutoFormFieldProps {
  error?: string | undefined;
  field: ParsedField;
  id: string;
  inputProps: AutoFormInputProps;
  label: UiRenderable;
  path: string[];
  value: unknown;
}

export type AutoFormFieldComponents<TFieldType extends string = string> = {
  fallback: React.ComponentType<AutoFormFieldProps>;
} & Partial<Record<TFieldType, React.ComponentType<AutoFormFieldProps>>>;

/**
 * Data-provider registry for AutoForm dropdowns.
 *
 * AutoForm is RPC-agnostic: the registry only knows about option lists.
 * Each provider is a React hook that returns `{ options, isLoading?, error? }`.
 * Whether the options are a static array or backed by an RPC is a concern
 * of the hosting app's wiring layer, not AutoForm.
 *
 * The registry is keyed by a string id that mirrors a proto `DataProviderId`
 * enum. The hosting app registers one implementation per id; a CI test
 * enumerates the proto descriptors and asserts completeness.
 */

import type React from "react";

export interface DataProviderOption {
  /** Optional helper line shown beneath the label. */
  description?: string;
  /** Optional group heading so related options cluster visually. */
  group?: string;
  /**
   * Optional glyph rendered before the label. Most useful when a dropdown
   * combines options from multiple sources and a visual mark helps users
   * distinguish them. Lists from one source should usually omit a repeated
   * icon because it adds noise without new information.
   */
  icon?: React.ReactNode;
  /** Display label shown in the dropdown. */
  label: string;
  /** Wire value stored in form state. */
  value: string;
}

export interface DataProviderResult {
  /** Non-null when the provider failed to load. */
  error?: unknown;
  /** True while an async source is loading. Static providers may omit this. */
  isLoading?: boolean;
  options: DataProviderOption[];
}

/**
 * A data provider is a React hook. Implementations may call `useQuery`,
 * return a memoised constant array, or anything in between — AutoForm
 * never inspects the internals.
 */
export type DataProvider = () => DataProviderResult;

export type DataProviderRegistry = Record<string, DataProvider>;

/**
 * Resolve a data provider by id. Returns `undefined` when the id is not
 * registered; the caller is responsible for rendering a graceful fallback
 * (and, in dev, logging a warning).
 */
export function resolveDataProvider(
  registry: DataProviderRegistry | undefined,
  id: string | undefined
): DataProvider | undefined {
  if (!(registry && id)) {
    return;
  }
  return registry[id];
}

import type { ParsedField } from "../../lib/form-types";

// Common protocol / tech acronyms the default title-casing would
// otherwise emit as mixed-case ("Api Key", "Tls", "Aws Region", etc.).
// The replacement is the canonical form the industry uses — gRPC is
// intentionally lower-case `g`, everything else is fully upper.
// Matched as whole words (case-insensitive) after the initial
// camelCase/snake_case split in `beautifyLabel`.
const ACRONYMS: Record<string, string> = {
  api: "API",
  aws: "AWS",
  dsn: "DSN",
  gcp: "GCP",
  grpc: "gRPC",
  http: "HTTP",
  https: "HTTPS",
  id: "ID",
  json: "JSON",
  jwt: "JWT",
  mcp: "MCP",
  oauth: "OAuth",
  sasl: "SASL",
  sdk: "SDK",
  sns: "SNS",
  sql: "SQL",
  sqs: "SQS",
  ssl: "SSL",
  tls: "TLS",
  tts: "TTS",
  uri: "URI",
  url: "URL",
  uuid: "UUID",
  vpc: "VPC",
  yaml: "YAML",
};

function applyAcronyms(label: string): string {
  return label.replace(/\b[A-Za-z]+\b/g, (word) => ACRONYMS[word.toLowerCase()] ?? word);
}

function beautifyLabel(label: string): string {
  if (!label) {
    return "";
  }
  let output = label.replace(/([A-Z])/g, " $1");
  output = output.charAt(0).toUpperCase() + output.slice(1);
  if (!Number.isNaN(Number(output))) {
    return "";
  }
  if (output === "*") {
    return "";
  }
  return applyAcronyms(output);
}

export function getLabel(field: ParsedField): string {
  return (field.fieldConfig?.label as string) || (field.description as string) || beautifyLabel(field.key);
}

export function sortFieldsByOrder<TFieldType extends string = string>(
  fields: ParsedField<TFieldType>[] | undefined
): ParsedField<TFieldType>[] {
  if (!fields) {
    return [];
  }
  return fields
    .map((field) => (field.schema ? { ...field, schema: sortFieldsByOrder(field.schema) } : field))
    .sort((a, b) => (a.fieldConfig?.order ?? 0) - (b.fieldConfig?.order ?? 0));
}

export function getPathInObject(obj: Record<string, unknown>, path: string[]): unknown {
  let current: unknown = obj;
  for (const key of path) {
    if (current === undefined || current === null) {
      return;
    }
    current = (current as Record<string, unknown>)[key];
  }
  return current;
}

"use client";

import { AlertCircle, ChevronDown, CircleHelp, ExternalLink, PlusIcon, TrashIcon } from "lucide-react";
import React from "react";
import { cn, type SharedProps } from "../../lib/utils";
import { Alert, AlertDescription, AlertTitle } from "../alert";
import { Button } from "../button";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "../collapsible";
import { Field, FieldContent, FieldDescription, FieldError, FieldLabel } from "../field";
import { Tooltip, TooltipContent, TooltipTrigger } from "../tooltip";
import { Heading, Text } from "../typography";
import { useAutoFormRuntimeContext } from "./context";
import type { ArrayElementWrapperProps, ArrayWrapperProps, FieldWrapperProps, ObjectWrapperProps } from "./core-types";
import { formSpacing } from "./form-spacing";
import { getFieldDescriptionText, getFieldDocsUrl, getFieldHelpText, getFieldUiConfig } from "./helpers";
import { FormDepthProvider, headingLevelForDepth, useFormDepth } from "./layout-context";
import { getAutoFormFieldTestId } from "./test-ids";

const REGEX_ERROR_PATTERN = /regex pattern\s*`([^`]+)`/;

export const Form = React.forwardRef<HTMLFormElement, React.ComponentProps<"form"> & SharedProps>(
  ({ children, testId, ...props }, ref) => (
    <form className={formSpacing.form} data-testid={testId} ref={ref} {...props}>
      <FormDepthProvider depth={0}>{children}</FormDepthProvider>
    </form>
  )
);
Form.displayName = "Form";

export const ArrayElementWrapper: React.FC<
  ArrayElementWrapperProps & {
    testId?: string;
    removeButtonTestId?: string;
  }
> = ({ children, onRemove, removeButtonTestId, testId }) => (
  <div
    className="relative rounded-xl border border-border/70 bg-card p-5 text-card-foreground shadow-xs"
    data-testid={testId}
  >
    <Button
      aria-label="Remove item"
      className="absolute top-3 right-3"
      onClick={onRemove}
      size="icon-sm"
      testId={removeButtonTestId}
      type="button"
      variant="ghost"
    >
      <TrashIcon className="h-4 w-4" />
    </Button>
    <div className="pr-8">{children}</div>
  </div>
);

export const ArrayWrapper: React.FC<
  ArrayWrapperProps & {
    addButtonTestId?: string;
    testId?: string;
  }
> = ({ label, children, onAddItem, addButtonTestId, testId }) => (
  <div className={formSpacing.field} data-testid={testId}>
    {children}
    <Button onClick={onAddItem} size="sm" testId={addButtonTestId} type="button" variant="outline">
      <PlusIcon className="h-4 w-4" />
      {label ? `Add ${label}` : "Add item"}
    </Button>
  </div>
);

export const ErrorMessage: React.FC<{ error: string }> = ({ error }) => (
  <Alert variant="destructive">
    <AlertCircle className="h-4 w-4" />
    <AlertTitle>AutoForm error</AlertTitle>
    <AlertDescription>{error}</AlertDescription>
  </Alert>
);

function augmentError(
  error: FieldWrapperProps["error"],
  field: FieldWrapperProps["field"]
): FieldWrapperProps["error"] {
  if (!(typeof error === "string" && REGEX_ERROR_PATTERN.test(error))) {
    return error;
  }
  const uiConfig = getFieldUiConfig(field);
  if (uiConfig.example) {
    return `${error}\nExample: ${uiConfig.example}`;
  }
  return error;
}

export const FieldWrapper: React.FC<FieldWrapperProps> = ({ label, children, id, field, error: rawError }) => {
  const depth = useFormDepth();
  const { testIdPrefix } = useAutoFormRuntimeContext();
  const isCompact = Boolean((field.fieldConfig?.customData as Record<string, unknown> | undefined)?.["compactRow"]);
  const tooltipText = isCompact ? "" : getFieldHelpText(field);
  const helpText = isCompact ? undefined : getFieldDescriptionText(field);
  const docsUrl = isCompact ? undefined : getFieldDocsUrl(field);
  const error = augmentError(rawError, field);
  const isDisabled = Boolean(field.fieldConfig?.inputProps?.["disabled"]);
  const hasVisibleLabel = !(typeof label === "string" && label.trim().length === 0);
  const fallbackLabel =
    typeof field.fieldConfig?.label === "string" && field.fieldConfig.label.trim().length > 0
      ? field.fieldConfig.label
      : field.key;
  const helpLabel = typeof label === "string" && label.trim().length > 0 ? label : fallbackLabel;
  const displayedLabel: React.ReactNode = hasVisibleLabel ? label : fallbackLabel;
  const fieldTestId = getAutoFormFieldTestId(testIdPrefix, id);
  const isSplit = depth === 0 && !isCompact;
  let fieldFeedback: React.ReactNode = null;
  if (error) {
    fieldFeedback = <FieldError testId={getAutoFormFieldTestId(testIdPrefix, id, "error")}>{error}</FieldError>;
  } else if ((helpText || docsUrl) && !isCompact) {
    fieldFeedback = (
      <FieldDescription testId={getAutoFormFieldTestId(testIdPrefix, id, "description")}>
        {helpText ? <span>{helpText}</span> : null}
        {docsUrl ? (
          <>
            {helpText ? " " : null}
            <a
              className="inline-flex items-center gap-1 text-primary underline-offset-2 hover:underline"
              data-testid={getAutoFormFieldTestId(testIdPrefix, id, "docs-link")}
              href={docsUrl}
              rel="noreferrer"
              target="_blank"
            >
              View {helpLabel} documentation
              <ExternalLink aria-hidden className="h-3 w-3" />
            </a>
          </>
        ) : null}
      </FieldDescription>
    );
  }

  // Match the non-AutoForm usage pattern in managed-create-form.tsx:
  // `<Field>` with label / control / description / error as *direct*
  // siblings, so the Field component's native `gap-3` drives the
  // label → input → description → error rhythm. The previous
  // `<Field gap-2><FieldContent gap-2>` nesting produced a cramped
  // 8px label/input gap and misaligned the internal rhythm from every
  // manually-constructed form in the app — users could spot the
  // AutoForm at a glance from the tighter stack alone.
  return (
    <Field
      className={
        isSplit ? "grid items-start gap-x-8 gap-y-2 sm:grid-cols-[minmax(10rem,0.34fr)_minmax(0,1fr)]" : undefined
      }
      data-disabled={isDisabled}
      data-invalid={Boolean(error)}
      data-layout={isSplit ? "split" : "stacked"}
      testId={fieldTestId}
    >
      {isCompact ? null : (
        <div className={cn("flex min-w-0 items-center gap-2", isSplit && "sm:pt-2")}>
          <FieldLabel className={hasVisibleLabel ? "items-center gap-2" : "sr-only"} htmlFor={id}>
            <Text as="span" variant="labelStrongSmall">
              {displayedLabel}
            </Text>
            {field.required ? (
              <Text as="span" className="text-destructive" variant="small">
                *
              </Text>
            ) : null}
          </FieldLabel>
          {tooltipText ? (
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  aria-label={`Help for ${helpLabel}`}
                  className="rounded-full text-muted-foreground shadow-none hover:text-foreground"
                  data-testid={getAutoFormFieldTestId(testIdPrefix, id, "help")}
                  size="icon-xs"
                  type="button"
                  variant="ghost"
                >
                  <CircleHelp className="h-4 w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent
                className="max-w-sm text-pretty text-xs"
                role="tooltip"
                testId={getAutoFormFieldTestId(testIdPrefix, id, "help-content")}
              >
                {tooltipText}
              </TooltipContent>
            </Tooltip>
          ) : null}
        </div>
      )}
      <FieldContent className="min-w-0 gap-2">
        {children}
        {fieldFeedback}
      </FieldContent>
    </Field>
  );
};

export const ObjectWrapper: React.FC<
  ObjectWrapperProps & {
    testId?: string | undefined;
    hasError?: boolean | undefined;
  }
> = ({ label, children, field, testId, hasError }) => {
  const depth = useFormDepth();
  const headingLevel = headingLevelForDepth(depth);
  const helpText = getFieldDescriptionText(field);
  const hasVisibleLabel = !(typeof label === "string" && label.trim().length === 0);
  const customData = (field.fieldConfig?.customData ?? {}) as Record<string, unknown>;
  const isCollapsible = Boolean(customData["collapsible"]);
  // Divider under a section header. Defaults to true for parity with the
  // historical ObjectWrapper behavior. Consumers can opt out by setting
  // `customData.showDivider = false` — same escape hatch as FormSection's
  // `divider` prop so both entry points agree on when a rule renders.
  const showDivider = customData["showDivider"] !== false && hasVisibleLabel;
  const isSplit = depth === 0 && hasVisibleLabel && !isCollapsible;
  const [isOpen, setIsOpen] = React.useState(false);

  // Auto-expand when section has validation errors
  React.useEffect(() => {
    if (hasError && !isOpen) {
      setIsOpen(true);
    }
  }, [hasError, isOpen]);

  if (isCollapsible && hasVisibleLabel) {
    return (
      <Collapsible onOpenChange={setIsOpen} open={isOpen}>
        <section className={formSpacing.field} data-testid={testId}>
          <CollapsibleTrigger asChild>
            <button
              className={
                showDivider
                  ? `flex w-full items-center justify-between text-left ${formSpacing.sectionDivider}`
                  : "flex w-full items-center justify-between text-left"
              }
              type="button"
            >
              <div className={formSpacing.sectionHeader}>
                <div className="flex items-center gap-2">
                  <Heading className="font-medium" level={headingLevel}>
                    {label}
                  </Heading>
                  {field.required ? (
                    <Text as="span" className="text-destructive" variant="small">
                      *
                    </Text>
                  ) : null}
                </div>
                {helpText ? (
                  <Text className="text-muted-foreground" variant="small">
                    {helpText}
                  </Text>
                ) : null}
              </div>
              <ChevronDown className="h-4 w-4 shrink-0 text-muted-foreground transition-transform duration-200 [[data-state=open]_&]:rotate-180" />
            </button>
          </CollapsibleTrigger>
          <CollapsibleContent>
            <FormDepthProvider depth={depth + 1}>
              <div className={formSpacing.field}>{children}</div>
            </FormDepthProvider>
          </CollapsibleContent>
        </section>
      </Collapsible>
    );
  }

  return (
    <section
      className={
        isSplit
          ? "grid items-start gap-6 sm:grid-cols-[minmax(10rem,0.34fr)_minmax(0,1fr)] sm:gap-x-8"
          : formSpacing.field
      }
      data-layout={isSplit ? "split" : "stacked"}
      data-testid={testId}
    >
      {hasVisibleLabel ? (
        <div
          className={
            showDivider
              ? `${formSpacing.sectionHeader} ${formSpacing.sectionDivider} ${isSplit ? "sm:border-b-0 sm:pb-0" : ""}`
              : formSpacing.sectionHeader
          }
        >
          <div className="flex items-center gap-2">
            <Heading className="font-medium" level={headingLevel}>
              {label}
            </Heading>
            {field.required ? (
              <Text as="span" className="text-destructive" variant="small">
                *
              </Text>
            ) : null}
          </div>
          {helpText ? (
            <Text className="text-muted-foreground" variant="small">
              {helpText}
            </Text>
          ) : null}
        </div>
      ) : null}
      <FormDepthProvider depth={depth + 1}>
        <div className={cn("min-w-0", formSpacing.field)}>{children}</div>
      </FormDepthProvider>
    </section>
  );
};

