        <Calendar
          mode="single"
          onSelect={(date) => {
            inputProps["onValueChange"](date ? format(date, "yyyy-MM-dd") : "");
          }}
          selected={selectedDate}
        />
      </PopoverContent>
    </Popover>
  );
