"use client";

import { KeyValueField } from "../../key-value-field";
import type { AutoFormFieldProps } from "../core-types";
import {
  denormalizeKeyValueEntries,
  getFieldUiConfig,
  normalizeKeyValueEntries,
  resolveRenderFieldType,
} from "../helpers";
import { getProtoFieldCustomData } from "../proto";
import type { FieldTypeDefinition } from "../registry";
import { useFieldTestIds } from "./shared";

function KeyValueFieldComponent({ field, id, inputProps }: AutoFormFieldProps) {
  const testIds = useFieldTestIds(id);
  const valueField =
    field.type === "map"
      ? field.schema?.[1]
      : field.schema?.[0]?.schema?.find((candidate) => candidate.key === "value");
  const valueRenderType = valueField ? resolveRenderFieldType(valueField) : undefined;
  const protoData = getProtoFieldCustomData(field);

  const valueFieldProps =
    valueRenderType === "select" || valueRenderType === "combobox" || valueRenderType === "radio"
      ? {
          mode: "combobox" as const,
          options: (valueField?.options || []).map(([value, optionLabel]) => ({ label: optionLabel, value })),
          placeholder: getFieldUiConfig(valueField ?? field).placeholder || "Value",
        }
      : {
          placeholder: getFieldUiConfig(valueField ?? field).placeholder || "Value",
        };

  return (
    <KeyValueField
      addButtonLabel="Add pair"
      disabled={inputProps["disabled"]}
      keyFieldProps={{ placeholder: "Key" }}
      maxItems={protoData?.maxPairs}
      onChange={(entries) => inputProps["onValueChange"](denormalizeKeyValueEntries(entries, field))}
      showAddButton
      testId={testIds.control}
      value={normalizeKeyValueEntries(inputProps["value"])}
      valueFieldProps={valueFieldProps}
    />
  );
}

export { KeyValueFieldComponent };

/**
 * Helper to check if a field's schema entry is a scalar type suitable for key-value use.
 */
function isKeyValueScalarField(field: { type?: string | undefined } | undefined): boolean {
  if (!field) {
    return false;
  }
  return ["string", "email", "url", "password", "currency", "number", "int64", "select", "combobox"].includes(
    field.type ?? ""
  );
}

function isSimpleKeyValueLikeObject(
  field:
    | {
        type?: string | undefined;
        schema?: Array<{ key: string; type?: string | undefined }> | undefined;
      }
    | undefined
): boolean {
  if (!(field?.type === "object" && field.schema?.length === 2)) {
    return false;
  }

  const keyField = field.schema.find((candidate) => candidate.key === "key");
  const valueField = field.schema.find((candidate) => candidate.key === "value");
  return Boolean(keyField && valueField && isKeyValueScalarField(keyField) && isKeyValueScalarField(valueField));
}

export const keyValueFieldDefinition: FieldTypeDefinition = {
  component: KeyValueFieldComponent,
  match: (field) => {
    // Array with key-value-like object items
    if (field.type === "array") {
      const itemField = field.schema?.[0];
      return isSimpleKeyValueLikeObject(itemField);
    }

    // Map with scalar key + value
    if (field.type === "map") {
      const keyField = field.schema?.[0];
      const valueField = field.schema?.[1];
      return isKeyValueScalarField(keyField) && isKeyValueScalarField(valueField);
    }

    return false;
  },
  name: "keyValue",
  priority: 18,
};

"use client";

import { SimpleMultiSelect } from "../../multi-select";
import { useAutoForm } from "../context";
import type { AutoFormFieldProps } from "../core-types";
import { resolveDataProvider } from "../data-providers";
import { getFieldUiConfig, NUMERIC_OPTION_PATTERN } from "../helpers";
import type { FieldTypeDefinition } from "../registry";
import { getGroupedOptions, readDataProviderId, renderOptionLabel, useFieldTestIds } from "./shared";

function MultiSelectFieldComponent({ field, id, inputProps }: AutoFormFieldProps) {
  const testIds = useFieldTestIds(id);
  const itemField = field.schema?.[0];
  const numericOptions = Boolean(itemField?.options?.every(([value]) => NUMERIC_OPTION_PATTERN.test(value)));
  const optionGroups = itemField ? getGroupedOptions(itemField) : undefined;
  const options = optionGroups?.length
    ? optionGroups.map((group) => ({
        children: group.options.map((option) => ({
          label: renderOptionLabel(option),
          selectedTestId: testIds.selected(option.value),
          testId: testIds.option(option.value),
          value: option.value,
        })),
        heading: group.label,
        testId: testIds.group(String(group.label ?? "group")),
      }))
    : (itemField?.options || []).map(([value, optionLabel]) => ({
        label: optionLabel,
        selectedTestId: testIds.selected(value),
        testId: testIds.option(value),
        value,
      }));

  return (
    <SimpleMultiSelect
      {...(inputProps["disabled"] === undefined ? {} : { disabled: inputProps["disabled"] })}
      id={id}
      onValueChange={(values) =>
        inputProps["onValueChange"](numericOptions ? values.map((value) => Number(value)) : values)
      }
      options={options}
      placeholder={getFieldUiConfig(field).placeholder || "Select one or more options"}
      testId={testIds.field}
      value={Array.isArray(inputProps["value"]) ? inputProps["value"].map((value: unknown) => String(value)) : []}
      width="full"
    />
  );
}

export { MultiSelectFieldComponent };

export const multiselectFieldDefinition: FieldTypeDefinition = {
  component: MultiSelectFieldComponent,
  match: (field) => {
    if (field.type !== "array") {
      return false;
    }
    const itemField = field.schema?.[0];
    return Boolean(itemField?.type === "select" && itemField.options?.length);
  },
  name: "multiselect",
  priority: 20,
};

// ── Data-provider-backed multi-select ─────────────────────────────────
// Matches `repeated string` whose item carries a `data_provider`
// annotation, e.g. OpenAPI `include_methods` / `exclude_methods`. The
// previous behavior rendered a list of single dropdowns with an "Add"
// button — one row per method. A multi-select collapses that to a single
// control that holds every picked method as a chip.

function DataProviderMultiSelectComponent({ field, id, inputProps }: AutoFormFieldProps) {
  const testIds = useFieldTestIds(id);
  const itemField = field.schema?.[0];
  const providerId = readDataProviderId(itemField);
  const { dataProviders } = useAutoForm();
  const provider = resolveDataProvider(dataProviders, providerId);
  const { options: providerOptions = [], isLoading } = provider ? provider() : { options: [] };

  const options = providerOptions.map((option) => {
    // `label` is typed as ReactNode on MultiSelectOptionItem, so we can
    // render icon + text + description inline instead of stringifying.
    const labelNode = (
      <span className="flex items-center gap-2" key={option.value}>
        {option.icon ? (
          <span className="flex h-4 w-4 shrink-0 items-center justify-center [&>svg]:h-full [&>svg]:w-full">
            {option.icon}
          </span>
        ) : null}
        <span>{option.label}</span>
        {option.description ? <span className="text-muted-foreground text-xs">— {option.description}</span> : null}
      </span>
    );
    return {
      label: labelNode,
      selectedTestId: testIds.selected(option.value),
      testId: testIds.option(option.value),
      value: option.value,
    };
  });

  const currentValue = Array.isArray(inputProps["value"])
    ? inputProps["value"].map((value: unknown) => String(value))
    : [];

  return (
    <SimpleMultiSelect
      disabled={Boolean(inputProps["disabled"] || isLoading)}
      id={id}
      onValueChange={(values) => inputProps["onValueChange"](values)}
      options={options}
      placeholder={getFieldUiConfig(field).placeholder || (isLoading ? "Loading…" : "Select one or more options")}
      testId={testIds.field}
      value={currentValue}
      width="full"
    />
  );
}

export const dataProviderMultiselectFieldDefinition: FieldTypeDefinition = {
  component: DataProviderMultiSelectComponent,
  match: (field) => {
    if (field.type !== "array") {
      return false;
    }
    const itemField = field.schema?.[0];
    if (!itemField || (itemField.type !== "string" && itemField.type !== "number")) {
      return false;
    }
    return readDataProviderId(itemField) !== undefined;
  },
  name: "dataProviderMultiSelect",
  // Higher than the default `multiselect` (20) so an annotated item wins
  // over the legacy "array-of-select-enum" branch even when both match.
  priority: 120,
};

"use client";

import { Input } from "../../input";
import type { AutoFormFieldProps } from "../core-types";
import { getFieldUiConfig } from "../helpers";
import type { FieldTypeDefinition } from "../registry";
import { normalizeNumberValue, resolveNumericStep, useFieldTestIds } from "./shared";

function NumberFieldComponent({ error, field, id, inputProps }: AutoFormFieldProps) {
  const testIds = useFieldTestIds(id);
  const stepValue = resolveNumericStep(inputProps, normalizeNumberValue(inputProps["value"]));
  const inputValue = inputProps["value"];
  const displayValue = typeof inputValue === "number" || typeof inputValue === "string" ? inputValue : "";

  return (
    <Input
      aria-invalid={Boolean(error)}
      className={error ? "border-destructive" : ""}
      disabled={inputProps["disabled"]}
      id={id}
      inputMode="decimal"
      max={inputProps["max"] as number | undefined}
      min={inputProps["min"] as number | undefined}
      onBlur={inputProps["onBlur"]}
      onChange={(event) => {
        const nextValue = event.target.value;
        inputProps["onValueChange"](nextValue === "" ? undefined : Number(nextValue));
      }}
      placeholder={getFieldUiConfig(field).placeholder}
      step={stepValue}
      testId={testIds.control}
      type="number"
      value={displayValue}
    />
  );
}

export { NumberFieldComponent };

export const numberFieldDefinition: FieldTypeDefinition = {
  component: NumberFieldComponent,
  match: (field) => {
    if (field.type !== "number") {
      return false;
    }
    const min = Number(field.fieldConfig?.inputProps?.["min"]);
    const max = Number(field.fieldConfig?.inputProps?.["max"]);
    return !(Number.isFinite(min) && Number.isFinite(max));
  },
  name: "number",
  priority: 10,
};

