export type BadgeVariant = VariantProps<typeof badgeVariants>["variant"];
export type BadgeSize = VariantProps<typeof badgeVariants>["size"];

function Badge({
  className,
  variant,
  asChild = false,
  testId,
  icon,
  children,
  size,
  ref,
  ...props
}: React.ComponentProps<"span"> &
  SharedProps & {
    asChild?: boolean;
    icon?: React.ReactNode;
    variant?: BadgeVariant;
    size?: BadgeSize;
  }) {
  const Comp = asChild ? Slot : "span";

  // When asChild is used with Slot, we can only pass ONE child element
  // to satisfy React.Children.only(). In asChild mode, users must include
  // icons inside children instead of using the icon prop.
  const renderContent = () => {
    if (asChild) {
      return children;
    }

    // Normal badge mode - can have icon + children
    if (icon && children) {
      return (
        <>
          {icon}
          <span className="truncate">{children}</span>
        </>
      );
    }

    if (icon) {
      return icon;
    }

    if (children) {
      return <span className="truncate">{children}</span>;
    }

    return null;
  };

  return (
    <Comp
      className={cn(badgeVariants({ size, variant }), className)}
      data-slot="badge"
      data-testid={testId}
      ref={ref}
      {...props}
    >
      {renderContent()}
    </Comp>
  );
}

