          data-slot="command-sub-trigger"
          onSelect={() => ctx?.onOpenChange(true)}
          {...props}
        />
      }
    >
      {children}
      <ChevronRight className="ml-auto size-4" />
    </PopoverAnchor>
  );
}

interface CommandSubContentProps {
