MultiSelectEmpty.displayName = "MultiSelectEmpty";

export interface MultiSelectOptionSeparator {
  key: string;
  type: "separator";
}

export interface MultiSelectOptionGroup {
  children: MultiSelectOption[];
  heading?: React.ReactNode | undefined;
  key: string;
  testId?: string | undefined;
  value?: string | undefined;
}

export type MultiSelectOption =
  | Pick<MultiSelectItemProps, "value" | "label" | "disabled" | "onSelect" | "onDeselect" | "selectedTestId" | "testId">
  | MultiSelectOptionSeparator
  | MultiSelectOptionGroup;

function findMultiSelectOption(
  options: MultiSelectOption[] | undefined,
  value: string
): MultiSelectOptionItem | undefined {
  for (const option of options ?? []) {
    if ("type" in option) {
      continue;
    }
    if ("children" in option) {
      const item = findMultiSelectOption(option.children, value);
      if (item) {
        return item;
      }
      continue;
    }
    if (option.value === value) {
      return {
        label: option.label,
        selectedTestId: option.selectedTestId,
        testId: option.testId,
        value,
      };
    }
  }
  return;
}

function renderMultiSelectOptions(list: MultiSelectOption[]) {
  return list.map((option) => {
    if ("type" in option) {
      if (option.type === "separator") {
        return <MultiSelectSeparator key={option.key} />;
      }

      return null;
    }

    if ("children" in option) {
      return (
        <MultiSelectGroup
          heading={option.heading}
          key={option.key}
          testId={option.testId}
          {...(option.value === undefined ? {} : { value: option.value })}
        >
          {renderMultiSelectOptions(option.children)}
        </MultiSelectGroup>
      );
    }

    return (
      <MultiSelectItem key={option.value} {...option} testId={option.testId}>
        {option.label}
      </MultiSelectItem>
    );
  });
}

// Simplified API for backend developers
type SimpleMultiSelectProps = PortalRootProps &
  SharedProps &
  Pick<PortalContentProps, "container" | "onOpenAutoFocus"> & {
    id?: string;
    options: MultiSelectOption[] | string[];
    value?: string[];
    onValueChange?: (value: string[]) => void;
    placeholder?: string;
    className?: string;
    disabled?: boolean;
    maxCount?: number;
    maxDisplay?: number;
    searchable?: boolean;
    width?: "sm" | "md" | "lg" | "xl" | "full" | "auto";
  };

const widthClasses = {
  auto: "w-auto",
  full: "w-full",
  lg: "w-80",
  md: "w-64",
  sm: "w-48",
  xl: "w-96",
};

function SimpleMultiSelect({
  id,
  options,
  value,
  onValueChange,
  placeholder = "Select items...",
  className,
  disabled,
  maxCount,
  maxDisplay,
  searchable = true,
  width = "md",
  container,
  open,
  defaultOpen,
  onOpenChange,
  testId,
}: SimpleMultiSelectProps) {
  // Convert simple string array to option objects
  const normalizedOptions: MultiSelectOption[] = React.useMemo(
    () =>
      options.map((option) => {
        if (typeof option === "string") {
          return { label: option, value: option };
        }
        return option;
      }),
    [options]
  );

  return (
    <MultiSelect
      defaultOpen={defaultOpen}
      disabled={disabled}
      maxCount={maxCount}
      onOpenChange={onOpenChange}
      onValueChange={onValueChange}
      open={open}
      testId={testId}
      value={value}
    >
      <MultiSelectTrigger
        className={cn(widthClasses[width], className)}
        id={id}
        testId={testId ? `${testId}-control` : undefined}
      >
        <MultiSelectValue
          maxDisplay={maxDisplay}
          options={normalizedOptions}
          placeholder={placeholder}
          testId={testId}
        />
      </MultiSelectTrigger>
      <MultiSelectContent container={container} testId={testId ? `${testId}-content` : undefined}>
        {searchable ? (
          <MultiSelectSearch placeholder="Search..." testId={testId ? `${testId}-search` : undefined} />
        ) : null}
        <MultiSelectList>{renderMultiSelectOptions(normalizedOptions)}</MultiSelectList>
        <MultiSelectEmpty>No items found</MultiSelectEmpty>
      </MultiSelectContent>
    </MultiSelect>
  );
}

export {
  MultiSelect,
  MultiSelectContent,
  MultiSelectEmpty,
  MultiSelectGroup,
  MultiSelectItem,
  MultiSelectList,
  MultiSelectSearch,
  MultiSelectSeparator,
  MultiSelectTrigger,
  MultiSelectValue,
  renderMultiSelectOptions,
  SimpleMultiSelect,
};

"use client";

import { Popover as PopoverPrimitive } from "@base-ui/react/popover";
import { AnimatePresence, type HTMLMotionProps, motion, type Transition } from "motion/react";
import React from "react";

import { usePortalContainer } from "@/registry/base-nova/protoform/hooks/use-portal-container";
import {
  asChildTrigger,
  narrowOpenChange,
  renderWithDataState,
  Slot,
  useMirroredOpen,
} from "@/registry/base-nova/protoform/lib/base-ui-compat";
import { cn, type PortalContentProps, type SharedProps } from "@/registry/base-nova/protoform/lib/utils";

interface PopoverContextType {
  isOpen: boolean;
}

const PopoverContext = React.createContext<PopoverContextType | undefined>(undefined);

const usePopover = (): PopoverContextType => {
  const context = React.useContext(PopoverContext);
  if (!context) {
    throw new Error("usePopover must be used within a Popover");
  }
  return context;
};

interface PopoverAnchorContextType {
  anchorRef: React.RefObject<Element | null>;
  hasAnchor: boolean;
  setHasAnchor: (hasAnchor: boolean) => void;
}

const PopoverAnchorContext = React.createContext<PopoverAnchorContextType | undefined>(undefined);

type Side = "top" | "bottom" | "left" | "right";
type Align = "start" | "center" | "end";

const getInitialPosition = (side: Side) => {
  switch (side) {
    case "top":
      return { y: 15 };
    case "bottom":
      return { y: -15 };
    case "left":
      return { x: 15 };
    case "right":
      return { x: -15 };
    default:
      return {};
  }
};

type PopoverProps = Omit<React.ComponentProps<typeof PopoverPrimitive.Root>, "onOpenChange" | "children"> &
  SharedProps & {
    onOpenChange?: (open: boolean) => void;
    children?: React.ReactNode;
  };

function Popover({ children, testId, onOpenChange, ...props }: PopoverProps) {
  const { isOpen, handleOpenChange } = useMirroredOpen(props.open, props.defaultOpen, onOpenChange);
  const anchorRef = React.useRef<Element | null>(null);
  const [hasAnchor, setHasAnchor] = React.useState(false);

  const anchorCtx = React.useMemo<PopoverAnchorContextType>(
    () => ({ anchorRef, hasAnchor, setHasAnchor }),
    [hasAnchor]
  );
  const popoverContextValue = React.useMemo(() => ({ isOpen }), [isOpen]);

  return (
    <PopoverContext.Provider value={popoverContextValue}>
      <PopoverAnchorContext.Provider value={anchorCtx}>
        <PopoverPrimitive.Root
          data-slot="popover"
          data-testid={testId}
          {...props}
          onOpenChange={narrowOpenChange(handleOpenChange)}
        >
          {children}
        </PopoverPrimitive.Root>
      </PopoverAnchorContext.Provider>
    </PopoverContext.Provider>
  );
}

type PopoverTriggerProps = React.ComponentProps<typeof PopoverPrimitive.Trigger> &
  SharedProps & {
    asChild?: boolean;
  };

function PopoverTrigger({ className, testId, ...props }: PopoverTriggerProps) {
  return (
    <PopoverPrimitive.Trigger
      className={cn("cursor-pointer", className)}
      data-slot="popover-trigger"
      data-testid={testId}
      {...asChildTrigger(props)}
    />
  );
}

type PopoverContentProps = React.ComponentProps<typeof PopoverPrimitive.Popup> &
  HTMLMotionProps<"div"> &
  SharedProps &
  Pick<PortalContentProps, "container" | "onOpenAutoFocus"> & {
    transition?: Transition;
    side?: Side;
    align?: Align;
    sideOffset?: number;
    alignOffset?: number;
  };

function PopoverContent(contentProps: PopoverContentProps) {
  const {
    className,
    align = "center",
    side = "bottom",
    sideOffset = 4,
    alignOffset,
    transition = { damping: 25, stiffness: 300, type: "spring" },
    children,
    testId,
    container,
    ...props
  } = contentProps;
  Reflect.deleteProperty(props, "onOpenAutoFocus");
  const { isOpen } = usePopover();
  const initialPosition = getInitialPosition(side);
  const portalContainer = usePortalContainer();
  const anchorCtx = React.useContext(PopoverAnchorContext);

  return (
    <AnimatePresence>
      {isOpen ? (
        <PopoverPrimitive.Portal container={container ?? portalContainer} data-slot="popover-portal" keepMounted>
          <PopoverPrimitive.Positioner
            align={align}
            alignOffset={alignOffset}
            {...(anchorCtx?.hasAnchor && anchorCtx.anchorRef.current ? { anchor: anchorCtx.anchorRef } : {})}
            className="z-50"
            side={side}
            sideOffset={sideOffset}
          >
            <PopoverPrimitive.Popup render={renderWithDataState("div")} {...props}>
              <motion.div
                animate={{ opacity: 1, scale: 1, x: 0, y: 0 }}
                className={cn(
