interface PopoverAnchorProps {
  asChild?: boolean;
  children?: React.ReactNode;
  render?: React.ReactElement;
}

function PopoverAnchor({ asChild, children, render }: PopoverAnchorProps) {
  const ctx = React.useContext(PopoverAnchorContext);

  const setRef = React.useCallback(
    (node: Element | null) => {
      if (ctx) {
        ctx.anchorRef.current = node;
        ctx.setHasAnchor(Boolean(node));
      }
    },
    [ctx]
  );

  const renderedChild = render && children !== undefined ? React.cloneElement(render, undefined, children) : render;
  const child = renderedChild ?? (asChild && React.isValidElement(children) ? children : undefined);

  if (child) {
    return (
      <Slot data-slot="popover-anchor" ref={setRef as React.Ref<HTMLElement>}>
        {child}
      </Slot>
    );
  }

  return (
    <div data-slot="popover-anchor" ref={setRef as React.Ref<HTMLDivElement>}>
      {children}
    </div>
  );
}

