function renderToggleButton(
  props: React.ButtonHTMLAttributes<HTMLButtonElement>,
  state: { pressed?: boolean; disabled?: boolean }
) {
  const attrs: Record<string, unknown> = {
    "data-state": state.pressed ? "on" : "off",
